<?php
namespace App\Http\Controllers\Auth;
use App\Http\Controllers\Controller; use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\Hash;
class AuthController extends Controller { public function showLogin(){return view('auth.login');} public function login(Request $r){$c=$r->validate(['email'=>'required|email','password'=>'required']); if(Auth::attempt($c,$r->boolean('remember'))){$r->session()->regenerate();return redirect()->intended(route('dashboard'));} return back()->withErrors(['email'=>'Email atau password salah.'])->onlyInput('email');} public function showRegister(){return view('auth.register');} public function register(Request $r){$d=$r->validate(['name'=>'required|max:100','email'=>'required|email|max:150|unique:users','password'=>'required|min:8|confirmed']);$u=User::create(['name'=>$d['name'],'email'=>$d['email'],'password'=>Hash::make($d['password']),'role'=>'user']);Auth::login($u);return redirect()->route('dashboard')->with('success','Registrasi berhasil.');} public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect()->route('login');} }
